    val MAP: Map<String, DuaText> = mapOf(
        "dua_new_moon" to DuaText("নিউ ইয়র্ক সিটিস", "হে অল্লাহ, মসি থা অসি ঐখোয়গী মথক্তা থৌজাল, থাজবগী থৌজাল, ঙাক-শেনবা অমসুং ইসলামগা লোয়ননা থোরকপা য়াই। (হে থা,) ঐগী লোর্দ অমসুং অদোমগী লোর্দ অসি অল্লাহনি।", "অনৌবা নুমিৎ অমা লাক্কনু।", "অনৌবা থা খুদিংগী ওইবা সুন্না দুৱা।"),
        "dua_janaza_adult" to DuaText("জনাজা প্রার্থনা (প্রাপ্তবয়স্ক)", "হে অল্লাহ, ঐখোয়গী হিংলিবা অমসুং লৈখিদ্রবা, হৌজিক লৈরিবা অমসুং য়াওদবা, ঐখোয়গী নহা ওইরিবা অমসুং অহল ওইরবা, ঐখোয়গী নুপা অমসুং নুপীবু মাংহনবা। হে অল্লাহ, ঐখোয়না হিংলিবা মীওইবু ইসলামদা হিংবা য়াহল্লু, অমসুং ঐখোয়গী মনুংদগী কনাগুম্বা অমনা শিরবা তারবদি থাজদুনা মরম ওইদুনা মহাক্না শিরবা য়াহল্লু।", "অহুমশুবা তাংকককী মতুংদা লাই খোইরম্বদা অৱাবা ফোঙদোকখ্রে।", "লৈখিদ্রবা অহল অমগীদমক সনা দুআ।"),
        "dua_janaza_child" to DuaText("জনাজা প্রার্থনা (শিশু)", "হে অল্লাহ, মহাকপু ঐখোয়গী পুরিনবা (অমসুং হোস্ত) অমা ওইহনবিয়ু, মহাকপু ঐখোয়গী মনা অমসুং লন থুম অমা ওইহনবিয়ু, অমসুং মহাক্কী ৱাফমবু য়ানরবা ঐখোয়গী ৱাফমদা ৱা ঙাংবা মীওই অমা ওইহনবিয়ু।", "অঙাং অমগী ইনফেয়রেসনেল লাই খুরুমদা (নুপী অমগীদমক'ইজ'অলহা'হায়)।", "সনাহ দুআ অসি হানাফিসশিংনা পাঙথোকখি।"),
        "dua_mayyit_awf" to DuaText("লৈখিদ্রবশিংগীদমক্তা অকুপ্পা মরোল", "হে অল্লাহ, মহাকপু শাওগনবা, থৌজাল পীবা, অমসুং মহাকপু শাওগনবা। মহাক্কী ফজববু ইকাই খুম্ননিংঙাই ওইহনবা অমসুং মহাক্কী কবরবু পাক-চাউবা ওইহনবা, মহাকপু ঈশিং, উন অমসুং লৈঙোইনা লুহনবা, অমসুং অঙৌবা ফি-রোল অমনা লৈহাওদগী লুখ্রাবী তৌবগুম্না পাপশিংদগী ঙাকথোকপা।", "লাই খোইরম্বদা নত্ত্রগা লৈখিদ্রবশিংগীদমক।", "আউফ ইবন মালিক (আর. এ.) না মহাক অসি লৈখিদ্রবা মীওইনি হায়না খল্লি।"),
        "dua_visiting_graves" to DuaText("লাই য়েকপা", "ঐ ঈমান লাকপশিং অমসুং য়ুমশিং অসিদা লৈরিবা মুস্লিমশিং, অদোম্না শান্তি ফংবা য়াই। ঐখোয়না, করিগুম্বা অল্লাহনা পাম্লবদি, অদোম্না শরুক য়াগনি। ঐহাক্না অল্লাহদা ঐখোয়গী অমসুং অদোমগী য়াইফনবা হায়জরি।", "লাই য়েকপা মতমদা মশক থোকপা।", "কবরশিংদা চৎপসিনা মীওই অমবু শিবগী অমসুং অকোনবগী মতম অদু নীংশিংহল্লি।"),
        "dua_closing_eyes" to DuaText("লৈখিদ্রবশিংগী মমিৎ তানবা", "হে অল্লাহ, (মমিং)বু শাওহল্লু, থৌশিল পীবা মীওইশিংগী মরক্তা মহাক্কী থাক ৱাংহল্লো, মহাক্না থাদোরক্লিবাশিংগী মরক্তা মহাক্কী তুংলমচৎ ওইয়ু। হে মালেমশিংগী ইবরাক, ঐখোয়না অমসুং মহাকপু শাওহল্লু, মহাক্কী কবরবু পাক চাউথোক্লু অমসুং মঙালনা নিংহল্লো।", "লৈখিদ্রবশিংগী মমিৎ থিংবা মতমদা (মহাক্কী মমিং পল্লদুনা)।", "মসি প্রফেট সলিহ আলীহ ওসল্মনা অবু সলামাহ (রা.) গীদমক দুআ অমা ওইনা পীরম্মি।"),
        "dua_condolence" to DuaText("শোক (তা'জিয়া)", "মহাক্না লৌখিবসি তশেংনা অল্লাহ্না লৌগনি অমসুং মহাক্না পীখিবসি মহাক্কীনি, অমসুং মহাক্কী মফমদা লৈরিবা পুম্নমক অদুগী অকক্নবা মতম অমা লৈগনি, মরম অদুনা মতম কুইনা লৈয়ু অমসুং মনা ফংনবগীদমক থাজবা থম্মু।", "লৈখিদ্রবা মতুংদা ইমুং অমদা অৱাবা ফোঙদোকচরি।", "মসি মহাক্কী মচানুপীদা পাউতাক অমা থাবিরম্মি।"),
        "dua_placing_in_grave" to DuaText("লৈখিদ্রবশিংগী মফমদা ইকায় খুম্নবা উৎচরি", "আল্লাহগী মমিং অমসুং অল্লাহগী রসূলগী লম্বীদা।", "লৈখিদ্রবশিংবু কবরদা নমথরকপা মতমদা।", "শুংবগী সুন্নাহ দুআ।"),
        "dua_sneezing" to DuaText("শ্বর থোক্তবা", "থাগৎলিবসি অল্লাহনি।-অল্লাহনা নোংখৌ থৌজাল পীয়ু।-অল্লাহনা নোংখৌ থৌশিল পীয়ু অমসুং অদোম্না তৌফম থোকপা থবকশিংদু অমুক হন্না তৌউ।", "তুম্বা মতমদা; তাবা মীওই অদুনা'যারহামুকাল্লাহ'হায়না হায়, অদুগা তুম্বা মীওই অদুনা পাউখুম পীখি।", "মসি অতোপ্পা মুস্লিম অমগী মথক্তা লৈবা মহাক্কী অয়াম্বা ৱাহৈশিংগী মরক্তা অমনি।"),
        "dua_toilet_enter" to DuaText("শৌহন্দ্রিবা য়ুমগী মপান্দা থোক্কনু", "আল্লাহগী মমিংদা। হে অল্লাহ, ঐহাক্না নুপাগী অমসুং নুপীগী অশু-অনা জিনশিংদগী নংনা শরণ লৈ।", "পায়্দুনা কুম্থখিনবা ৱা ঙাংবা", "বিস্মিল্লাহ অসি জিন অমসুং মীওই অদুগী মরক্তা লৈবা স্ক্রীন অমা ওই।"),
        "dua_toilet_exit" to DuaText("শৌহন্দ্রিবা য়ুমদগী মপান্দা থোক্কনু", "(হে আল্লাহ,) ঐনা ঐগী ওজাশিংবু ইকায় খুম্নবা উৎচরি।", "পায়্দুনা কুম্থখিনবা ৱাশাং অমসু য়ুংগনি", "মসি প্রোফেট সলিহ আলীহ ওসল্মনা টোইলেৎ থাদোরকপা মতমদা হায়খি।"),
        "dua_thanking" to DuaText("মীওই অমবু ইকাই খুম্নবা উৎচরি।", "আল্লাহনা নংনা অফবা পুরিনবা ঙমহল্লোই।", "কনাগুম্বা অমনা মতেং পাংলবা মতুংদদি মসিদা কান্নগনি।", "অসুম্না হায়রম্বশিং অসিদা মহাক্না য়াম্না নুংঙাইবা ফাওই।"),
        "dua_love_for_allah" to DuaText("মীওই অমনা'I প্রণয় আপনি for God'হায়রগসু খঙনরবা ৱাফম অমা লৈ।", "মহাক (আল্লাহ) না ঐঙোন্দা য়াম্না নুংশিজবা মীওইনি।", "মীওই অমনা'I প্রণয় আপনি for the soal'হায়না হায়রকপা মতমদা।", "সুন্নাহনা অল্লাহগীদমক নুংশিবা হায়বসিগী পাউখুম পীরম্মি।"),
        "dua_seeing_muslim_smile" to DuaText("শুভেচ্ছা (সলাম)", "শান্তি অমসুং থৌগলগী ৱারীশিং, অমসুং মহাক্কী থৌজালশিং।", "মুসলমান অমা ওইনা লৌবা।", "মপুং ফানা সলাম হায়রগনা অফবা থবক তরাহুমদোই ফংই।"),
        "dua_dressing" to DuaText("শা-ঙাগী ওইবা", "মসি ঐহাক্না লৈতেংখিবা অমসুং শক্তি নত্ত্রগা শক্তি য়াওদনা ঐহাক্না ফংহনখিবা অল্লাহবু থাগৎলি।", "মহাক্না শাদুনা লৈরম্বদু।", "লৈখিদ্রবশিংগী মফমদা অৱাবা ফোঙদোকচরি।"),
        "dua_rooster_donkey" to DuaText("হঙ্গাম নত্ত্রগা হঙ্গাম", "হে অল্লাহ, ঐহাক্না তুম্বু মহাক্কী থৌজাল (উচেক) অদু পামজৈ।-ঐহাক্না শাপিত শয়তান (খোকা) দগী অল্লাহদা শরণ লৈ।", "হঙ্গাম অমনা অল্লাহগী থৌজাল পামজবদু তাবা মতমদা; হঙ্গাম অমনা হঙ্গাম শোক্নবদা শায়তানদগী শরণ লৌ।", "উচেক অদুনা দেবদূত অমা উবা ফংই অদুগা খোকা অদুনা শেবতবু উবা ফংই।"),
        "dua_something_liked" to DuaText("শিংথানিংঙাই ওইবা অমা উবা (ফত্তবা মীৎগী মায়োক্তা)", "আল্লাহনা পাম্লিবদু। হে আল্লাহ, মসি তৌবিগনু।", "কনাগুম্বা অমগী মশক থোকপা মশক অমা উবা ফংলবদি, থৌজাল ফংনবগীদমক লাই খোইরম্মি।", "থৌজালগীদমক লাই খোইরম্বনা ফত্তবা মীৎবু থিংলি।"),
        "dua_sell_buy_debt_repaid" to DuaText("শেল লৌথোকপা মতমদা", "আল্লাহনা নহাকপু ইমুং মনুং অমসুং লন-থুমদা থৌগল তৌহল্লোই।", "শেন্দোংগী চাংদা শেল থাদবা মতমদা শেন্দোংগী চাংদা শেল থাদবা।", "লোন অমগী রিটরন অসি থেংক্স অমসুং রিপেমেন্তনি।"),
        "dua_talbiyah" to DuaText("তালবিয়া", "ঐ মফম অসিদা লৈরি, হে অল্লাহ, মফম অসিদা লৈরি। মফম অসিদা লৈরি, মসিদা ঐগী শুপ্নতগী শুপ্নতগী শুপ্নতগী লৈনররোই, মফম অসিদা ঐহাক লৈরি। তশেংনা থাগৎনিংঙাই ওইবা, থৌজাল পীবা অমসুং লৈবাক শেম্বগী থবক পুম্নমক মসিনি। মফম অসিদা ঐগী শুপ্নতগী শুপ্নতগী লৈনররোই।", "ইহরামদা চঙলবা মতুংদা য়াম্না ৱানা লেং।", "হজ অমসুং উমরাহগী খুদম।"),
        "dua_yamani_hajar" to DuaText("রুকন যামানি অমসুং হাজার অসৱাদকী মরক্তা", "হে ঐখোয়গী ঈপূরোই, মালেম অসিদা ঐখোয়না অফবা অমসুং মাংজিল থোক্ত্রবদা ঐখোয়না অফবা ওইহনবিয়ু, অমসুং ঐখোয়না মৈগী অৱাবদগী ঙাকথোক্কদবনি।", "তাৱাফতা, য়েমেনি কর্নর অমসুং ব্লেক ষ্টোনগী মরক্তা।", "মসি তাৱাফকী মফম অসিদা প্রোফেট সলিহ আলীহ ওসল্মনা ইখি।"),
        "dua_safa_marwa" to DuaText("সাফা অমসুং মারৱা", "অচুম্বা লাইয়েংগী হক অসি অল্লাহ নত্তনা, অমত্তা ওইনা, শুপ্নতগী লৈজরক্তনা, কনা অমত্তদা লৈতে। মহাক্কী লৈঙাকসি, অমসুং মহাক্কী পুকচেল শেংবগী হক লৈ, অমসুং মহাক্কী শক্তি পুম্নমক লৈ। অল্লাহ খক্তদা নত্তনা কনাগুম্বা অমত্তনা পুকচেল শেংবগী হক লৈতে। মহাক্না মহাক্কী ৱারেপ অদু মপুং ফানা ফংহনখি, মহাক্কী থৌমীবু মতেং পাংখি অমসুং কনফেডেরেতশিংবু মায়থিবা পীখি।", "সাফা ওনবা অমসুং কিবলাহগী মাইয়োক্তা লৈবা (অহুম হন্না)।", "প্রোফেটের দিকর সলিহ আলীহ ওয়াস্লম সাফা এবং মারওয়াহ।"),
        "dua_arafah" to DuaText("আরাফাগী নুমিৎতা খ্বাইদগী ফবা দুআ", "অচুম্বা লাইয়েংগী হক অসি অল্লাহ নত্তনা, অমত্তা ওইনা, শুপ্নতগী লৈজরবসু, কনা অমত্তদা লৈতে। মহাক্কী লৈঙাকসি অমসুং মহাক্কী পুকচেল শেংবগী হকসু লৈ, অমসুং মহাক্না পোৎ খুদিংমক পাবদা শক্তি লৈ।", "অরাফাগী নুমিৎ-খ্বাইদগী ফবা দুআ।", "খ্বাইদগী ফবা দুআ অসি অরাফাগী নুমিৎতা পীবা দুআনি, অমসুং খ্বাইদগী ফবা ৱাহৈশিংদি মখোয় অসিনি।"),
        "dua_takbeer_tashreeq" to DuaText("তাকবীর-ই-তশরিক", "আল্লাহ অসি খ্বাইদগী চাউবা, অল্লাহনা খ্বাইদগী চাউবা। অল্লাহ নত্তনা লাইরেম্বী অমত্তা লৈতে। অল্লাহ অসি খ্বাইদগী চাউবা, অল্লাহনা খ্বাইদগী চাউবা, অমসুং পুকচেল শেংবা পুম্নমক অল্লাহনি।", "9 ধুল-হিজ্জাগী ফজরদগী 13 ধুল-হিজ্জাগী আসর ফাওবা ফরবা লাই খোইরম্বা খুদিংগী মতুংদা।", "অলি অমসুং ইবন মাসউদ (আর. এ.) দগী রিপোর্ত তৌখি-হনাফিসকী মতুং ইন্না ৱাজিব।"),
        "dua_zamzam" to DuaText("জামজাম পানিং", "হে অল্লাহ, ঐহাক্না নোংখৌ কান্নবা লৌশিং, মরাং কায়না পীবা অমসুং লায়না খুদিংমক কোকহন্নবা হায়জরি।", "জামজাম য়ুবা মতমদা, অদোম্না পাম্লিবা অদুগীদমক দুআ শেম্মু।", "জামজাম অসি মসি য়ুবা অদুগীদমক ওই (ইবন মাজাহ 3062)।"),
        "dua_q_ma_khalaqta_batila" to DuaText("শেম্বিবা মপুনা শেম্বিবা মপুনা", "হে ঐখোয়গী ইশ্বর, অদোম্না মসি পুম্নমক কান্নদনা শেম্লমদে। অদোম্না চাওথোকচনিংঙাই ওই, মরম অদুনা ঐখোয়না মৈগী অৱাবদগী ঙাকথোক্কনি।", "স্বর্গ অমসুং পৃথীবিগী লৈমাইদা লৈরিবা কয়া অমবু মশক তাকপা।", "ৱাখল খনবা মীওইশিংগী দুআ (উলুল-অলবাব)।"),
        "dua_q_sami_na_munadiyan" to DuaText("ঐখোয়না থাজবগী ৱাফমদা কৌরিবা মীওই অদু নমথোক্লসি।", "হে ঐখোয়গী ইবরাহ, ঐখোয়না থাজনবা কৌরিবা মীওই অমবু'তুংলমচৎপু থাজবা থম্মু'হায়না কৌবদা ৱা ঙম্মি, অমসুং ঐখোয়না থাজবা থম্লি। হে ঐখোয়গী ইবরাহ, ঐখোয়গী পাপশিং অদু মাংহল্লু, ঐখোয়গী ফত্তবা থবকশিংবু অমদগী লৌথোকউ অমসুং অচুম্বা থবক তৌরিবা মীওইশিংগা লোয়ননা ঐখোয়না শিরু।", "অচুম্বা অমসুং অচুম্বা ৱাখল্লোন লৈবা মীওইশিংগী মরক্তা লৈবা থাজবগী অমসুং শিরবগী দুআ।", "ক্ষমা প্রার্থনা এবং একটি ভাল সমাপ্তি।"),
        "dua_q_atina_ma_waadtana" to DuaText("অদোম্না করি ৱারেপ লৌখিবনো হায়বা ঐখোয়না খঙই।", "হে ঐখোয়গী ঈপূরে, অদোম্না ঐখোয়গী রসূলশিংগী খুত্থাংদা ঐখোয়না ৱা ঙাংখিবদু ঐখোয়দা পীরিয়ু অমসুং নৌনা হল্লকপা নুমিত্তা ঐখোয়দা নীংথিজদনবা তৌ। তশেংনা, অদোম্না তৌব ৱারেপ অদু কায়দনবা তৌদে।", "নৌনা হল্লকপা নুমিৎতা নীংতম্বগী ৱাফমদগী ঙাকথোক্নবগীদমক।", "অকোনবা মতমদনা ইকায় খুম্নবা উৎচরি।"),
        "dua_q_israfana" to DuaText("ঐখোয়গী অথৌবশিং মমিৎ পাঙবা", "হে ঐখোয়গী লাইরেম্বী, ঐখোয়গী পাপশিং অমসুং ঐখোয়গী থবকশিংদা ঐখোয়না তৌরকপা অৱাবশিং অদু মাংহনবিয়ু, ঐখোয়গী খোঙফমশিং অদু মপাঙ্গল কনখৎহনবিয়ু অমসুং থাজদবা মীয়ামগী মায়োক্তা ঐখোয়দা মতেং পাংবিয়ু।", "হান্নগী প্রধান মন্ত্রীগা উনখিবা ৱারোলশিং", "অচুম্বা অমসুং ফিগরদা য়ুম্ফম ওইবা।"),
        "dua_q_jamiun_nas" to DuaText("মীওইবা জাতিগীদমক্তা শিজবা", "হে ঐখোয়গী ঈপূরে, অদোম্না মীওইববু করিগুম্বা ৱাফম অমতা লৈতে হায়বা নুমিৎ অমদা খোমজিন্দুনা থমগনি। তশেংনা, অল্লাহনা মহাক্কী ৱারেপ অদু কায়হন্দবা নত্তে।", "অমুক হন্না হিংবগী নুমিৎতা হন্না হন্না ময়াম পুম্নমকপু হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না", "লৌশিং-গ্যানদা মপুং ফানা য়ুম্ফম ওইবা মীওইশিংগী দুআ।"),
        "dua_q_maash_shahidin" to DuaText("সাক্ষীশিংগী মরক্তা ঐখোয়দা ইবীয়ু।", "ঐখোয়গী ইশ্বর, ঐখোয়না থাজবা থম্লি, মরম অসিনা ঐখোয়না সাক্ষীশিংগী মরক্তা ইবীয়ু।", "অচুম্বা অমসুং থাজববু মশক খঙলবা মীওইশিংগী দুআ।", "মীওই অমগী থাজববু শৌগৎপা অমা।"),
        "dua_q_la_tajalna_zalimin" to DuaText("ফত্তবা পোৎথোক হাৎপা মীশিংগা লোয়ননা", "হে ঐখোয়গী লাইরেম্বী, ঐখোয়না তৌবদু ফত্তবা মীশিংগা লোয়ননা তৌরোইদবনি।", "অল-অরাফকী মীয়ামগী দুআ।", "ফত্তবা তৌবশিংদগী ঙাকথোক্নবগীদমক।"),
        "dua_q_tawaffana_muslimin" to DuaText("মুসলমান হিসাবে ধৈর্য এবং মৃত্যু", "হে ঐখোয়গী লাইরেম্বী, ঐখোয়গী মফমদা থৌজাল থাদুনা অমসুং মুস্লিম ওইনা ঐখোয়গী পুন্সি মাঙহনবী।", "মখোয়না থাজখিবা মতমদা ফারাওগী মেজিকিয়নশিংগী দুআ।", "চাংয়েং তৌবদা থেংথরবা অমসুং থাজবদা লোইশিনবা।"),
        "dua_q_la_tajalna_fitnah" to DuaText("ইৎথ্নোগ্রফরশিংগীদমক্তা মসিদা ৱা ঙাংগনি।", "ঐখোয়না অল্লাহদা থাজবা থম্লি। হে ঐখোয়গী প্রভূ, ঐখোয়না তৌবীমল খঙবা মীশিংদা চাংয়েং তৌহল্লোই অমসুং নংনা তৌবীরিবা মীয়ামদগী ঐখোয়গী থৌজালবু ঙাকথোই।", "মুসা (AS) গী মীয়ামগী দুআ।", "অৱা-অনা অমসুং অৱা-অনাদগী ঙাকথোক্নবা হোৎনরিবা মীওই।"),
        "dua_q_nuh_ma_laysa_li" to DuaText("ক্ষমা চাওয়ার জন্য নুহ (এএস) এর দুআ", "হে ঐগী ইশ্বর, ঐহাক্না খঙবা ঙমদবা ৱাফমদু ঐহাক্না নাদুনা লৈরুবদা ঐহাক্না পুকনিংলি। অদুগা, অদোম্না ঐঙোন্দা তৌবীদবা অমসুং ঐঙোন্দা থৌজাল পীবা তারগদি, ঐহাক্না মাঙখিবাশিংগী মরক্তা ওইরগনি।", "প্রফেট নূহ (এ. এস.) গী ৱাফমদা মহাক্কী ৱাফমদা ৱা ঙাংগনি।", "অফবা লমচৎ শাজৎ লৈবা ৱাহং হংনবগী মহৈ অমা।"),
        "dua_q_mudkhala_sidq" to DuaText("অচুম্বা অমসুং ফিগরদা চঙবা", "হে ঐগী ইশ্বর, ঐহাক্না অচুম্বা ৱাহৈগা লোয়ননা চংলু অমসুং অচুম্বা ৱাহৈগা লোয়ননা মাংহন্দবা, অমসুং মশামক্তগী মতেং পাংনবা শক্তি অমা পীবা।", "অনৌবা থবক অমদা, য়ুম নত্ত্রগা মফম অমহেক্তদা শিজিন্নবা।", "দুৱা অসিনা হিজ্রাগী মতমদা প্রোফেট সলিহ আলীহ ওস্লমদা তাক্লম্মী।"),
        "dua_q_la_tadharni_fardan" to DuaText("দুৱা অফ জাকারিয়া (এ. এস.)-দোন্ট লিভ মি অলোন", "হে ঐগী লাইরেম্বী, ঐখক অসি মাংহন্দবা, অমসুং অদোম্না খ্বাইদগী ফবা ইনহেরিতেতরশিংনি।", "হায়রিবশিং অসি পীক্লিবা অঙাংশিংদনা অমুক্কা হেন্না থোকল্লি।", "মসিগী দুআগী খুত্থাংদা অল্লাহনা যাহ্যা (এ. এস.) পীখি।"),
        "dua_q_munzalan_mubarakan" to DuaText("নীংতম্বা য়াদবা লমগী মফম অমা", "হে ঐগী ইশ্বর, ঐহাক্না নীংথিরবা লৈতরবা মফমদা থুংলু, অমসুং অদোম্না লৈতরক্লিবা মীওইশিংগী মনুংদা খ্বাইদগী ফবা মীওইনি।", "অনৌবা য়ুম অমদা চৎপদা নত্ত্রগা মফম অমহেক্তদা থমবদা-নুহ (এ. এস.) গী দুআ।", "অনৌবা মফম অমদা থৌগল তৌনবগীদমক্তা হন্না হন্না ময়াম পুম্নমকপু হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না হন্না"),
        "dua_q_amanna_faghfir" to DuaText("ঐখোয়না থাজবা থম্লি, মরম অসিনা ঐখোয়না মখোয় পুম্নমক্তা চাউথোকচবা পোকচরি।", "হে ঐখোয়গী লাইরেম্বী, ঐখোয়না থাজবা থম্লি, মরম অসিনা ঐখোয়না তৌবীমল খঙবা অমসুং ঐখোয়গী থৌজালবু নীংশিংগদবনি, অমসুং অদোম্না তৌবীমল খঙবা মীওইশিংগী মনুংদা খ্বাইদগী ফবা মীওইনি।", "ঈশ্বরগী অশেংবা থৌমীশিংগী দোৱা।", "ক্ষমা এবং করুণার জন্য একটি সম্পূর্ণ ডুয়া।"),
        "dua_q_isrif_jahannam" to DuaText("নরকের শাস্তি", "হে ঐখোয়গী ঈপূরে, নরকগী অৱাবা অসি ঐদগী ঙাকথোক্কদবনি; মসিগী অৱাবা অসি মতম চুপ্পদা অদুমক অদুমক লৈরি। তশেংনমক্কী, মসি অফবা য়ুম্লোন্নফম অমসুং লৈফম অমনি।", "খ্বাইদগী করুণাময়ী ('ইবাদত অর-রহমান) গী সেবকশিংগী দুআ।", "নরক থেকে আশ্রয় নেওয়ার জন্য একটি কুরানিক দুআ।"),
        "dua_q_hab_li_hukman" to DuaText("দুয়া অফ ইব্রাহিম (এ. এস.)-ৱিজদম অমসুং জান্নাহ", "হে ঐগী ইশ্বর, ঐহাক্না লৌশিং পীবা অমসুং অচুম্বা মীওইশিংগা লোইননা শরুক য়াবা, মখা তারকপা চারোন-শুরোনগী মরক্তা ঐনা ইকায় খুম্ননিংঙাই ওইরবা ৱারোল অমা পীবা, অমসুং ঐহাক্না লৈকোলগী লন-থুমগী ইনহেরিতেতরশিংগী মরক্তা অমা ওইহনবী।", "অচুম্বা অমসুং স্বর্গগী কম্পেনী, ৱাখল থিবগী ৱাফম।", "ইব্রাহিম (এ. এস.) গী মপুং ওইবা দুআ অমা।"),
    )
}
